#include <moe_topk/protocol_i_permute_share.h>
#include <openssl/rand.h>
#include <array>
#include <chrono>
#include <cerrno>
#include <poll.h>
#include <stdexcept>
#include <unistd.h>
namespace moe_topk { namespace {
using Clock=std::chrono::steady_clock; [[noreturn]] void fail(const char*m){throw std::runtime_error(m);} ProtocolIBlock192 add(ProtocolIBlock192 a,const ProtocolIBlock192&b){return{a.word0+b.word0,a.word1+b.word1,a.word2+b.word2};} ProtocolIBlock192 sub(ProtocolIBlock192 a,const ProtocolIBlock192&b){return{a.word0-b.word0,a.word1-b.word1,a.word2-b.word2};}
void valid(const ProtocolIPermuteShareConfig&c){if(c.n<2||c.timeout_ms<=0||c.permutation_owner_party>1)fail("PS config");(void)protocol_i_benes_layout(c.n,c.subpermutation_size);}
void io(int fd,void*d,std::size_t n,bool send,Clock::time_point end){auto*p=static_cast<std::uint8_t*>(d);while(n){auto now=Clock::now();if(now>=end)fail("PS deadline");pollfd f{fd,static_cast<short>(send?POLLOUT:POLLIN),0};int r;do r=::poll(&f,1,static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(end-now).count()+1));while(r<0&&errno==EINTR);if(r<=0||(f.revents&(POLLERR|POLLHUP|POLLNVAL)))fail("PS transport");const auto k=send ? ::write(fd,p,n) : ::read(fd,p,n);if(k<0&&errno==EINTR)continue;if(k<=0)fail("PS EOF");p+=k;n-=static_cast<std::size_t>(k);}}
void put(std::vector<std::uint8_t>&v,std::uint64_t x){for(int i=7;i>=0;--i)v.push_back(static_cast<std::uint8_t>(x>>(8*i)));}std::uint64_t get(const std::uint8_t*&p){std::uint64_t x=0;for(int i=0;i<8;++i)x=(x<<8)|*p++;return x;}
void hello(const ProtocolIPermuteShareConfig&c,int fd,bool isdo,Clock::time_point end){std::array<std::uint64_t,7> f{{UINT64_C(0x4d32505300000001),c.session,c.fingerprint,c.online_message_id,c.n,c.subpermutation_size,c.permutation_owner_party}};std::array<std::uint8_t,56>b{};auto*p=b.data();for(auto x:f)for(int i=7;i>=0;--i)*p++=static_cast<std::uint8_t>(x>>(8*i));if(isdo){io(fd,b.data(),b.size(),true,end);io(fd,b.data(),b.size(),false,end);}else{io(fd,b.data(),b.size(),false,end);io(fd,b.data(),b.size(),true,end);}const auto*q=b.data();for(auto x:f)if(get(q)!=x)fail("PS online header");}
std::vector<ProtocolIBlock192> addv(const std::vector<ProtocolIBlock192>&a,const std::vector<ProtocolIBlock192>&b){if(a.size()!=b.size())fail("PS vector");auto r=a;for(std::size_t i=0;i<r.size();++i)r[i]=add(r[i],b[i]);return r;}std::vector<ProtocolIBlock192> subv(const std::vector<ProtocolIBlock192>&a,const std::vector<ProtocolIBlock192>&b){if(a.size()!=b.size())fail("PS vector");auto r=a;for(std::size_t i=0;i<r.size();++i)r[i]=sub(r[i],b[i]);return r;}std::vector<ProtocolIBlock192> papply(const ProtocolIPermutation&p,const std::vector<ProtocolIBlock192>&x){return protocol_i_apply_permutation(p,x);}ProtocolIPermuteShareCounters ctr(const ProtocolIChosenOtCounters&o,std::uint64_t tr,std::uint32_t t){std::uint32_t d=0;for(;t>1;t>>=1)++d;ProtocolIPermuteShareCounters r;r.offline_ot=o;r.offline_translation_instances=tr;r.offline_opv_instances=tr*(UINT64_C(1)<<d);r.offline_chosen_ot_items=r.offline_opv_instances*d;return r;}
} 
ProtocolIPermuteShareDoResult protocol_i_permute_share_do(const ProtocolIPermuteShareConfig&c,int off,int on,const std::vector<ProtocolIPermuteShareRecord>&x){valid(c);if(x.size()!=c.n)fail("PS input shape");const auto l=protocol_i_benes_layout(c.n,c.subpermutation_size);const auto tr=static_cast<std::uint32_t>(protocol_i_benes_translation_count(l));ProtocolIOpvConfig oc{c.session,c.fingerprint,c.offline_material_id,c.subpermutation_size,0,c.timeout_ms};const auto f=protocol_i_share_translation_fvo_batch(oc,off,tr);std::vector<std::vector<ProtocolIBlock192>>a(l.d,std::vector<ProtocolIBlock192>(c.n)),b=a;std::uint32_t k=0;for(std::uint32_t z=0;z<l.d;++z)for(std::size_t g=0;g<l.groups[z].size();++g,++k)for(std::uint32_t i=0;i<c.subpermutation_size;++i){a[z][l.groups[z][g][i]]=f.a[k][i];b[z][l.groups[z][g][i]]=f.b[k][i];}auto m=addv(x,a[0]);std::vector<std::vector<ProtocolIBlock192>>cv;for(std::uint32_t z=1;z<l.d;++z)cv.push_back(subv(a[z],b[z-1]));std::vector<ProtocolIBlock192>w(c.n);if(RAND_bytes(reinterpret_cast<unsigned char*>(w.data()),static_cast<int>(w.size()*sizeof(w[0])))!=1)fail("PS random");auto end=Clock::now()+std::chrono::milliseconds(c.timeout_ms);hello(c,on,true,end);std::vector<std::uint8_t>msg;for(auto&r:m){put(msg,r.word0);put(msg,r.word1);put(msg,r.word2);}for(auto&v:cv)for(auto&r:v){put(msg,r.word0);put(msg,r.word1);put(msg,r.word2);}for(auto&r:w){put(msg,r.word0);put(msg,r.word1);put(msg,r.word2);}io(on,msg.data(),msg.size(),true,end);auto r=ctr(f.counters,tr,c.subpermutation_size);r.online_sent_bytes=56+msg.size();return{subv(w,b.back()),r};}
ProtocolIPermuteSharePoResult protocol_i_permute_share_po(const ProtocolIPermuteShareConfig&c,int off,int on,const ProtocolIPermutation&p){valid(c);protocol_i_validate_permutation(p);if(p.size()!=c.n)fail("PS permutation shape");const auto d=protocol_i_benes_decompose(p,c.subpermutation_size);const auto tr=static_cast<std::uint32_t>(protocol_i_benes_translation_count(d.layout));std::vector<std::vector<std::uint32_t>>local;for(const auto&l:d.layers)for(const auto&q:l.local_permutations)local.push_back(q);ProtocolIOpvConfig oc{c.session,c.fingerprint,c.offline_material_id,c.subpermutation_size,0,c.timeout_ms};const auto po=protocol_i_share_translation_po_batch(oc,off,local);std::vector<std::vector<ProtocolIBlock192>>delta(d.layout.d,std::vector<ProtocolIBlock192>(c.n));std::uint32_t k=0;for(std::uint32_t z=0;z<d.layout.d;++z)for(std::size_t g=0;g<d.layout.groups[z].size();++g,++k)for(std::uint32_t i=0;i<c.subpermutation_size;++i)delta[z][d.layout.groups[z][g][i]]=po.delta[k][i];auto end=Clock::now()+std::chrono::milliseconds(c.timeout_ms);hello(c,on,false,end);std::vector<std::uint8_t>msg(static_cast<std::size_t>(d.layout.d+1)*c.n*24);io(on,msg.data(),msg.size(),false,end);const auto*q=msg.data();auto read=[&](){std::vector<ProtocolIBlock192>v(c.n);for(auto&r:v)r={get(q),get(q),get(q)};return v;};auto m=read();std::vector<std::vector<ProtocolIBlock192>>cv;for(std::uint32_t z=1;z<d.layout.d;++z)cv.push_back(read());auto w=read(),acc=delta[0];for(std::uint32_t z=1;z<d.layout.d;++z)acc=addv(delta[z],papply(d.layers[z].permutation,addv(cv[z-1],acc)));auto r=ctr(po.counters,tr,c.subpermutation_size);r.online_received_bytes=56+msg.size();return{subv(addv(papply(p,m),acc),w),r};}
}  // namespace moe_topk
